namespace SirketMotoru.Isletim;

internal static class SirketYonetimHtml
{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Şirket Yönetim Merkezi V9.1</title><style>
:root{color-scheme:dark;--bg:#050912;--p:#0b1525;--p2:#111f34;--l:#29415f;--t:#edf7ff;--m:#92a9c7;--g:#43e1a0;--b:#61a8ff;--r:#ff6b7d;--y:#ffd166}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#14365f 0,transparent 34%),radial-gradient(circle at 92% 0,#321c59 0,transparent 30%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}.hide{display:none!important}.shell{max-width:2200px;margin:auto}.top{position:sticky;top:5px;z-index:30;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 15px;border:1px solid var(--l);border-radius:15px;background:#071220f5}.brand{font-size:19px;font-weight:1000}.brand small{display:block;color:var(--m);font-size:9px}.row,.tabs,.actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.tabs{margin:10px 0}.tab,button{cursor:pointer;border:1px solid var(--l);border-radius:9px;padding:8px 11px;background:#0a1628;color:var(--t);font-weight:800}.tab.active,button.primary{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.danger{border-color:#85404c;color:#ff9dac}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.card,.item,.metric{border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091423)}.card{padding:12px;margin-bottom:10px}.item{padding:10px}.metrics{display:grid;grid-template-columns:repeat(8,minmax(110px,1fr));gap:7px;margin:10px 0}.metric{padding:9px}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:5px;font-size:15px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px}.title h2,.item h3{margin:0;font-size:14px}.item p,.card p{color:var(--m);font-size:9px}.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.tablewrap{overflow:auto;max-height:690px;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1050px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}input,select{width:100%;padding:7px;border-radius:8px;border:1px solid var(--l);background:#071322;color:var(--t)}input[type=checkbox]{width:auto}input[type=range]{padding:0}.range{display:grid;grid-template-columns:1fr 80px;gap:7px;align-items:center}.bar{height:8px;background:#14233a;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.login{max-width:440px;margin:12vh auto;padding:20px;border:1px solid var(--l);border-radius:16px;background:var(--p)}.login h1{margin-top:0}.field{margin:11px 0}.field label{display:block;color:var(--m);font-size:10px;margin-bottom:5px}.msg{min-height:20px;font-size:10px;margin-top:8px}@media(max-width:1500px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){.top{position:static;align-items:flex-start;flex-direction:column}.metrics,.grid,.grid3,.grid4{grid-template-columns:1fr}}
</style></head><body>
<section id="login" class="login"><h1>Şirket Yönetim Merkezi V9.1</h1><p class="sub">Giriş yapılmadan canlı durum isteği gönderilmez; ekran kendi kendine yenilenmez.</p><form id="loginForm"><div class="field"><label>Kullanıcı adı</label><input id="user" autocomplete="username" required></div><div class="field"><label>Parola</label><input id="pass" type="password" autocomplete="current-password" required></div><button class="primary" type="submit">Giriş yap</button><div id="loginMsg" class="msg"></div></form></section>
<div id="app" class="shell hide"><header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ V9.1<small>Tek ekonomi · fiziksel kapasite · sabit hizmet fiyatı · 500 hizmet · 200 kategori</small></div><div class="row"><span class="pill">Şirket <b id="company">—</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Durum <b id="conn">Bağlanıyor</b></span><button id="logout">Çıkış</button></div></header><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"></nav><main id="root"></main><div id="toast" class="msg"></div></div>
<script>
'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));
const T=[['overview','Genel'],['demand','Arz & Talep'],['capacity','Kapasite Tahsisi'],['products','Uygulama & OS'],['services','500 Hizmet'],['categories','200 Kategori'],['protocols','Protokoller'],['sla','SLA'],['investments','Yatırımlar'],['finance','Finans & Banka'],['account','Hesap']];
const S={d:null,a:T.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview',auth:false,loading:false,last:-1,hold:0,pending:false};
function hold(ms=900){S.hold=Math.max(S.hold,Date.now()+ms)}function editing(){const e=document.activeElement;return !!e&&/INPUT|SELECT|TEXTAREA/.test(e.tagName)}function scrolls(){const m={w:window.scrollY};document.querySelectorAll('[data-scroll]').forEach(x=>m[x.dataset.scroll]=x.scrollTop);return m}function restore(m){requestAnimationFrame(()=>{window.scrollTo(0,m.w||0);document.querySelectorAll('[data-scroll]').forEach(x=>{if(m[x.dataset.scroll]!=null)x.scrollTop=m[x.dataset.scroll]})})}
function tabs(){$('#tabs').innerHTML=T.map(x=>`<button class="tab ${S.a===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('')}function tab(id){if(!T.some(x=>x[0]===id))id='overview';S.a=id;history.replaceState(null,'',`#${id}`);tabs();render(true)}
function showLogin(msg=''){$('#app').classList.add('hide');$('#login').classList.remove('hide');S.auth=false;S.d=null;S.last=-1;$('#loginMsg').textContent=msg}function showApp(){$('#login').classList.add('hide');$('#app').classList.remove('hide');S.auth=true;tabs()}
async function api(path,opt={}){const r=await fetch(path,{cache:'no-store',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let j=null;try{j=await r.json()}catch{}if(r.status===401){showLogin('Oturum gerekli veya süresi doldu.');throw new Error('401')}if(!r.ok)throw new Error(j?.aciklama||j?.message||`HTTP ${r.status}`);return j}
async function refresh(force=false){if(!S.auth||S.loading)return;S.loading=true;try{const d=await api('/api/durum');S.d=d;const t=Number(d.v9?.sonTick??d.tickNumarasi??0);$('#conn').textContent='Çalışıyor';$('#tick').textContent=t;$('#company').textContent=d.sirket?.sirketAdi||d.sirket?.sirketKimligi||'—';if(force||t!==S.last){S.last=t;if(editing()||Date.now()<S.hold){S.pending=true}else render()}}catch(e){if(e.message!=='401')$('#conn').textContent='Bağlantı yok'}finally{S.loading=false}}
function render(force=false){if(!S.d||(!force&&(editing()||Date.now()<S.hold))){S.pending=true;return}const pos=scrolls();S.pending=false;$('#metrics').innerHTML=metricHtml(S.d);const fn={overview,demand,capacity,products,services,categories,protocols,sla,investments,finance,account}[S.a]||overview;$('#root').innerHTML=fn(S.d);restore(pos)}
function metricHtml(d){const s=d.sirket||{},v=d.v9||{},o=v.sirketOzeti||{},k=v.kapasite||{};return [['Kasa',money(s.kasa)],['Tick net',money(o.netKazanc)],['Hizmet geliri',money(o.hizmetGeliri)],['Uygulama geliri',money(o.uygulamaGeliri)],['Gider',money(Number(o.isletmeGideri||0)+Number(o.finansmanGideri||0))],['Borç',money(o.aktifBorc)],['Kapasite',`${int(k.kullanilanKapasite)}/${int(k.toplamFizikselKapasite)}`],['OS kullanıcı',int(o.isletimSistemiKullanicisi)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function overview(d){const s=d.sirket||{},i=d.isletim||{},v=d.v9||{},o=v.sirketOzeti||{},k=v.kapasite||{},p=k.toplamFizikselKapasite?k.kullanilanKapasite*100/k.toplamFizikselKapasite:0;return `<div class="notice"><b>V9.1 kuralı:</b> Çevrimdışı şirket gider, kredi, SLA ve ürün ekonomisinde donar. Hizmet fiyatları değiştirilemez. Kapasite satın alınmaz; altyapı yatırımıyla büyütülüp aşağıdaki panelden tahsis edilir.</div><div class="grid4"><div class="item"><h3>Finans</h3><p>Kasa <b>${money(s.kasa)}</b></p><p>Tick net <b class="${Number(o.netKazanc)>=0?'good':'bad'}">${money(o.netKazanc)}</b></p><p>Ödenemeyen gider ${money(i.odenemeyenGider)}</p></div><div class="item"><h3>Kapasite</h3><p>${int(k.kullanilanKapasite)} / ${int(k.toplamFizikselKapasite)} · %${num(p)}</p><div class="bar"><i style="width:${Math.min(100,p)}%"></i></div><p>Boş ${int(k.bosKapasite)}</p></div><div class="item"><h3>Puanlar</h3><p>Kalite ${num(s.kodKalitesiPuani)} · performans ${num(s.performansPuani)}</p><p>Güvenlik ${num(s.guvenlikPuani)} · güvenilirlik ${num(s.guvenilirlikPuani)}</p></div><div class="item"><h3>Pazar</h3><p>Uygulama kullanıcısı ${int(o.aktifUygulamaKullanicisi)}</p><p>OS kullanıcısı ${int(o.isletimSistemiKullanicisi)}</p><p>Aktif borç ${money(o.aktifBorc)}</p></div></div>${demand(d)}`}
function tr(x){return `<span class="${Number(x.degisimYuzdesi)>=0?'good':'bad'}">${Number(x.degisimYuzdesi)>=0?'▲':'▼'} %${num(Math.abs(x.degisimYuzdesi))}</span> ${esc(x.aktifTrend||'normal')}`}
function demand(d){const v=d.v9||{},apps=v.uygulamaTalepleri||[],hs=v.hizmetTalepleri||[],os=v.isletimSistemiTalebi||{};return `<div class="grid"><div class="card"><div class="title"><h2>Uygulama talebi</h2><span class="tag">${int(apps.length)} kategori</span></div><div class="tablewrap" data-scroll="demand-app"><table><tr><th>Kategori</th><th>Talep</th><th>Karşılanan</th><th>Arz</th><th>Açık</th><th>Trend</th></tr>${apps.map(x=>`<tr><td>${esc(x.ad)}<br><span class="sub">${esc(x.kategoriSektoru)}</span></td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.arzKapasitesi)}</td><td class="${x.karsilanamayanTalep?'warn':'good'}">${int(x.karsilanamayanTalep)}</td><td>${tr(x)}</td></tr>`).join('')}</table></div></div><div class="card"><h2>İşletim sistemi</h2><p>Talep <b>${int(os.buTickTalep)}</b> · karşılanan <b>${int(os.karsilananTalep)}</b> · açık <b>${int(os.karsilanamayanTalep)}</b></p><div class="grid3">${(os.arzDagilimi||[]).map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.sirketAdi)}</p><p>${int(x.karsilanan)} kullanıcı · %${num(x.pazarPayi)}</p><p>${money(x.fiyat)}</p></div>`).join('')||'<p>Aktif OS arzı yok.</p>'}</div><h2>En yüksek hizmet açıkları</h2><div class="tablewrap" data-scroll="demand-service"><table><tr><th>Hizmet</th><th>Talep</th><th>Karşılanan</th><th>Açık</th><th>Trend</th></tr>${hs.slice(0,150).map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${tr(x)}</td></tr>`).join('')}</table></div></div></div>`}
function capacity(d){const s=d.sirket||{},i=d.isletim||{},k=d.v9?.kapasite||{},t=k.tahsisler||{},hs=s.hizmetler||[],us=i.urunler||[];return `<div class="notice">Toplam fiziksel havuz <b>${int(k.toplamFizikselKapasite)}</b>. Tahsis toplamı bu değeri aşamaz. Sıfır tahsis gerçek sıfır kapasitedir.</div><form id="capacityForm"><div class="grid"><div class="card"><h2>Hizmet tahsisleri</h2><div class="tablewrap" data-scroll="cap-service"><table><tr><th>Hizmet</th><th>Sabit fiyat</th><th>Tahsis</th><th>Eşzamanlı iş</th></tr>${hs.filter(x=>x.aktif).map(h=>{const key=`hizmet:${h.hizmetKimligi}@${h.hizmetSurumu}`,v=Number(t[key]||0);return `<tr><td>${esc(h.hizmetKimligi)}@${esc(h.hizmetSurumu)}</td><td>${money(h.birimFiyat)}</td><td><div class="range"><input type="range" min="0" max="${int(k.toplamFizikselKapasite)}" step="10" value="${v}" data-cap="${esc(key)}"><b data-out>${int(v)}</b></div></td><td>${int(h.azamiEszamanliIs)}</td></tr>`}).join('')}</table></div></div><div class="card"><h2>Uygulama / OS tahsisleri</h2><div class="tablewrap" data-scroll="cap-product"><table><tr><th>Ürün</th><th>Tür</th><th>Tahsis</th><th>Kullanıcı kapasitesi</th><th>Aktif</th></tr>${us.filter(x=>x.aktif).map(u=>{const key=`urun:${u.urunKimligi}`,v=Number(t[key]||0);return `<tr><td>${esc(u.urunAdi)}</td><td>${esc(u.urunTuru)}</td><td><div class="range"><input type="range" min="0" max="${int(k.toplamFizikselKapasite)}" step="5" value="${v}" data-cap="${esc(key)}"><b data-out>${int(v)}</b></div></td><td>${int(u.kullaniciKapasitesi)}</td><td>${int(u.aktifKullaniciSayisi)}</td></tr>`}).join('')}</table></div></div></div><div class="actions"><button class="primary" type="submit">Tahsisi kaydet</button><span id="capTotal" class="tag">Ayrılan ${int(k.ayrilmisKapasite)} / ${int(k.toplamFizikselKapasite)}</span></div></form>`}
function products(d){const manifests=d.kodTabanliYayinlar?.uygulamalar||[],urunler=d.isletim?.urunler||[],oslar=d.ekosistem?.isletimSistemleri||[],protos=(d.protokolKataloguV9||[]).filter(x=>x.kullanilabilir),ranges=d.fiyatAraliklariV9||{};return `<div class="grid">${manifests.map(x=>{const m=x.uygulama||{},u=urunler.find(z=>z.urunKimligi===x.urunKimligi),r=ranges[u?.urunKimligi||`manifest:${m.uygulamaKimligi}`]||{min:1,max:120,adim:1,onerilen:25},id=encodeURIComponent(m.uygulamaKimligi||'x'),isOs=m.urunTuru==='isletim-sistemi';if(!u)return `<div class="card product" data-app="${esc(m.uygulamaKimligi)}"><div class="title"><h2>${esc(m.uygulamaAdi)}</h2><span class="tag">Yayınlanmadı</span></div><p>${esc(m.urunTuru)} / ${esc(m.kategori)}</p><label>Fiyatlandırma<select data-model><option value="abonelik">Abonelik</option><option value="kullanim">Kullanım</option><option value="freemium">Freemium</option></select></label><label>Fiyat <span data-price-out>${money(r.onerilen)}</span><input data-price type="range" min="${r.min}" max="${r.max}" step="${r.adim}" value="${r.onerilen}"></label>${isOs?'':`<label>İşletim sistemi<select data-os><option value="">Seçin</option>${oslar.map(o=>`<option value="${esc(o.uygulamaKimligi)}">${esc(o.uygulamaAdi)} · ${esc(o.sirketAdi)}</option>`).join('')}</select></label>`}<label>Protokol<select data-proto><option value="">Seçin</option>${protos.map(p=>`<option value="${esc(p.protokolKimligi)}">${esc(p.protokolAdi)} · ${esc(p.sahipSirketAdi)}</option>`).join('')}</select></label><button class="primary" data-action="publish">OS + protokolle yayına al</button><p class="${x.dogrulama?.gecerli?'good':'bad'}">${esc(x.dogrulama?.durum||'')}</p></div>`;const f=u.fiyatlandirmaModeli==='kullanim'?u.kullanimBasinaUcret:u.abonelikUcreti,p=u.kullaniciKapasitesi?u.aktifKullaniciSayisi*100/u.kullaniciKapasitesi:0;return `<div class="card product" data-product="${esc(u.urunKimligi)}"><div class="title"><h2>${esc(u.urunAdi)}</h2><span class="tag ${u.aktif?'good':'warn'}">${u.aktif?'Aktif':'Pasif'}</span></div><p>${esc(u.urunTuru)} / ${esc(u.kategori)}</p><p>Kullanıcı ${int(u.aktifKullaniciSayisi)} / ${int(u.kullaniciKapasitesi)} · %${num(p)}</p><label>Fiyat <span data-price-out>${money(f)}</span><input data-price type="range" min="${r.min}" max="${r.max}" step="${r.adim}" value="${f}"></label><label><input data-active type="checkbox" ${u.aktif?'checked':''}> Yayında</label><button data-action="price">Fiyat ve durumu kaydet</button><p>Toplam gelir ${money(u.toplamGelir)}</p></div>`}).join('')||'<div class="notice">Şirket manifestinde uygulama veya işletim sistemi yok.</div>'}</div>`}
function services(d){const market=d.v9?.hizmetTalepleri||[],own=d.sirket?.hizmetler||[],map=new Map(own.map(x=>[`${x.hizmetKimligi}@${x.hizmetSurumu}`,x]));return `<div class="notice">Motorun 500 hizmeti sabit fiyatlıdır. “Bende var” işareti şirket manifesti ve gerçek sunucu ilanından gelir.</div><div class="tablewrap card" data-scroll="services"><table><tr><th>Hizmet</th><th>Aile</th><th>Bende</th><th>Durum</th><th>Sabit fiyat</th><th>Talep</th><th>Karşılanan</th><th>Açık</th><th>İşlem</th></tr>${market.map(x=>{const h=map.get(x.anahtar),fam=String(x.anahtar).split('.')[0];return `<tr><td>${esc(x.anahtar)}</td><td>${esc(fam)}</td><td class="${h?'good':'bad'}">${h?'VAR':'YOK'}</td><td>${h?(h.aktif?'Aktif':'Pasif'):'—'}</td><td>${money((x.arzDagilimi||[])[0]?.fiyat||0)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${h?`<button data-action="service-toggle" data-service="${esc(h.hizmetKimligi)}" data-version="${esc(h.hizmetSurumu)}" data-next="${h.aktif?'false':'true'}">${h.aktif?'Pasifleştir':'Aktifleştir'}</button>`:'—'}</td></tr>`}).join('')}</table></div>`}
function categories(d){const cats=d.v9?.uygulamaTalepleri||[],own=new Set((d.sirket?.hizmetler||[]).filter(x=>x.aktif).map(x=>x.hizmetKimligi)),apps=d.kodTabanliYayinlar?.uygulamalar||[];return `<div class="notice">Hazır kategoriler, zorunlu hizmetlerin tamamı şirkette aktifse yeşil görünür. Ek uygun hizmetler ürün kalitesine katkı sağlar.</div><div class="tablewrap card" data-scroll="categories"><table><tr><th>Kategori</th><th>Sektör</th><th>Zorunlu hizmetler</th><th>Eksikler</th><th>Hizmet hedefi</th><th>Kapasite tüketimi</th><th>Pazar açığı</th><th>Uygulamalarım</th></tr>${cats.map(c=>{const z=c.zorunluHizmetler||[],e=z.filter(x=>!own.has(x)),mine=apps.filter(x=>(x.uygulama?.kategori||'')===c.anahtar).map(x=>x.uygulama?.uygulamaAdi).filter(Boolean);return `<tr><td><b>${esc(c.ad)}</b><br>${esc(c.anahtar)}</td><td>${esc(c.kategoriSektoru)}</td><td>${z.map(esc).join('<br>')||'—'}</td><td class="${e.length?'bad':'good'}">${e.map(esc).join('<br>')||'HAZIR'}</td><td>${int(c.asgariHizmetSayisi)} / ${int(c.onerilenHizmetSayisi)} / ${int(c.azamiHizmetSayisi)}</td><td>Taban ${num(c.tabanKapasiteTuketimi)}<br>Kullanıcı ${num(c.kullaniciBasinaKapasiteTuketimi)}</td><td>${int(c.karsilanamayanTalep)}</td><td>${mine.map(esc).join('<br>')||'—'}</td></tr>`}).join('')}</table></div>`}
function protocols(d){const ps=d.protokolKataloguV9||[],mine=d.kodTabanliYayinlar?.protokoller||[];return `<div class="grid"><div class="card"><h2>Tek kanonik protokol pazarı</h2><div class="tablewrap" data-scroll="protocol-market"><table><tr><th>Protokol</th><th>Sahip</th><th>Durum</th><th>Lisans</th><th>İşlem</th></tr>${ps.map(p=>`<tr><td>${esc(p.protokolAdi)}<br>${esc(p.protokolKimligi)} v${esc(p.surum)}</td><td>${esc(p.sahipSirketAdi)}</td><td>${p.sahibi?'Kendi':p.benimsendi?'Benimsendi':p.kullanilabilir?'Açık':'Kapalı'}</td><td>${money(p.benimsemeBedeli)} + ${money(p.tickLisansBedeli)}/tick</td><td>${!p.sahibi&&!p.benimsendi&&p.aktif?`<button data-action="adopt-proto" data-market="${esc(p.piyasaKaydiKimligi)}">Benimse</button>`:'—'}</td></tr>`).join('')}</table></div></div><div class="card"><h2>Sunucumun protokolleri</h2>${mine.map(x=>{const p=x.protokol||{};return `<div class="item"><h3>${esc(p.protokolAdi)}</h3><p>${esc(p.protokolKimligi)} v${esc(p.surum)}</p><p class="${x.gecerli?'good':'bad'}">${x.gecerli?'Teknik olarak hazır':'Eksik: '+(x.eksikYetkinlikler||[]).join(', ')}</p>${x.piyasada?'Piyasada':`<button data-action="publish-proto" data-proto="${esc(p.protokolKimligi)}" data-version="${esc(p.surum)}">Piyasaya aç</button>`}</div>`}).join('')||'<p>Özel protokol ilan edilmedi.</p>'}</div></div>`}
function sla(d){const offers=d.sozlesmeTeklifleri||[],active=d.isletim?.sozlesmeler||[],s=d.sirket||{},own=s.hizmetler||[],cap=own.filter(x=>x.aktif).reduce((a,x)=>a+Number(x.azamiEszamanliIs||0),0);const fam=k=>k==='analitik'?['veri','analitik']:k==='eposta'?['eposta']:k==='sosyal-medya'?['sosyal']:k==='guvenlik'?['guvenlik']:['platform','isletim-sistemi'].includes(k)?['isletim']:k==='altyapi'?['isletim','veritabani']:[];return `<div class="grid"><div class="card"><h2>Açık SLA teklifleri</h2>${offers.map(x=>{const f=fam(x.kategori),service=f.length===0?own.some(h=>h.aktif):own.some(h=>h.aktif&&f.some(a=>h.hizmetKimligi.startsWith(a+'.'))),missing=[];if(!s.bagliMi)missing.push('sunucu çevrimdışı');if(Number(s.kodKalitesiPuani)<x.asgariKalite)missing.push('kalite');if(Number(s.performansPuani)<x.asgariPerformans)missing.push('performans');if(Number(s.guvenlikPuani)<x.asgariGuvenlik)missing.push('güvenlik');if(cap<x.gerekliKapasite)missing.push('kapasite');if(!service)missing.push('hizmet ailesi');return `<div class="item"><div class="title"><h3>${esc(x.baslik)}</h3><span class="tag ${missing.length?'bad':'good'}">${missing.length?'UYGUN DEĞİL':'UYGUN'}</span></div><p>${esc(x.kategori)} · ${int(x.sureTick)} tick · ${money(x.tickOdemesi)}/tick</p><p>Kalite ${num(x.asgariKalite)} · performans ${num(x.asgariPerformans)} · güvenlik ${num(x.asgariGuvenlik)} · kapasite ${int(x.gerekliKapasite)}</p><p>${missing.length?'Eksik: '+missing.join(', '):'Bütün şartlar sağlanıyor.'}</p><button data-action="sla" data-offer="${esc(x.teklifKimligi)}" ${missing.length?'disabled':''}>Kabul et</button></div>`}).join('')||'<p>Açık teklif yok.</p>'}</div><div class="card"><h2>Aktif sözleşmeler</h2>${active.filter(x=>x.aktif).map(x=>`<div class="item"><h3>${esc(x.baslik)}</h3><p>Tick ${int(x.baslangicTicki)}–${int(x.bitisTicki)} · ödeme ${money(x.tickOdemesi)}</p><p>Başarılı ${int(x.basariliTickSayisi)} · ihlal ${int(x.ihlalSayisi)}</p></div>`).join('')||'<p>Aktif sözleşme yok.</p>'}</div></div>`}
function investments(d){return `<div class="grid4">${(d.yatirimMagazasi||[]).map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.aciklama)}</p><p>Seviye <b>${int(x.seviye)}</b> · kapasite katkısı ${int(x.kapasiteKatkisi)}</p><p>Sonraki maliyet <b>${money(x.sonrakiMaliyet)}</b></p><button data-action="invest" data-type="${esc(x.yatirimTuru)}">Yükselt</button></div>`).join('')}</div>`}
function finance(d){const i=d.isletim||{},o=d.v9?.sirketOzeti||{},credits=i.krediler||[],ops=i.sonIslemler||[];return `<div class="grid"><div class="card"><h2>Bu tick gelir-gider</h2><div class="grid3"><div class="item"><h3>Gelirler</h3><p>Hizmet ${money(o.hizmetGeliri)}</p><p>Uygulama ${money(o.uygulamaGeliri)}</p><p>Abonelik ${money(o.abonelikGeliri)}</p><p>Protokol ${money(o.protokolGeliri)}</p></div><div class="item"><h3>Giderler</h3><p>İşletme ${money(o.isletmeGideri)}</p><p>Finansman ${money(o.finansmanGideri)}</p><p>Ödenemeyen ${money(i.odenemeyenGider)}</p></div><div class="item"><h3>Sonuç</h3><p>Net <b class="${Number(o.netKazanc)>=0?'good':'bad'}">${money(o.netKazanc)}</b></p><p>Kredi notu ${int(i.krediNotu)}</p><p>Şirket değeri ${money(i.sirketDegeri)}</p></div></div></div><div class="card"><h2>İsteğe bağlı kredi</h2><form id="creditForm"><input id="creditAmount" type="number" min="5000" max="250000" step="1000" value="25000"><button type="submit">Kredi kullan</button></form><p>Toplam faiz sabittir; gecikmede borç katlanmaz. Otomatik kurtarma kredisi yoktur.</p>${credits.filter(x=>x.aktif).map(x=>`<div class="item"><b>${esc(x.krediTuru)}</b> · kalan ${money(x.kalanBorc)} · taksit ${money(x.taksitTutari)} · sonraki ${int(x.sonrakiOdemeTicki)}</div>`).join('')}</div></div><div class="card"><h2>Son muhasebe hareketleri</h2><div class="tablewrap" data-scroll="finance-ops"><table><tr><th>Tick</th><th>Tür</th><th>Açıklama</th><th>Tutar</th></tr>${ops.map(x=>`<tr><td>${int(x.tickNumarasi)}</td><td>${esc(x.islemTuru)}</td><td>${esc(x.aciklama)}</td><td class="${Number(x.tutar)>=0?'good':'bad'}">${money(x.tutar)}</td></tr>`).join('')}</table></div></div>`}
function account(d){return `<div class="card"><h2>Parola değiştir</h2><form id="passwordForm" class="grid"><label>Mevcut parola<input id="oldPass" type="password" required></label><label>Yeni parola<input id="newPass" type="password" minlength="8" required></label><div><button class="primary" type="submit">Parolayı değiştir</button></div></form><p>${d.parolaDegistirilmeli?'Geçici parolayı değiştirmeniz gerekiyor.':'Parola kalıcı olarak ayarlı.'}</p></div>`}
async function post(path,body){const r=await api(path,{method:'POST',body:JSON.stringify(body)});$('#toast').textContent=r.aciklama||'İşlem tamamlandı.';hold(400);await refresh(true);return r}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginMsg').textContent='Giriş yapılıyor…';try{await api('/api/giris',{method:'POST',body:JSON.stringify({kullaniciAdi:$('#user').value,parola:$('#pass').value})});showApp();await refresh(true)}catch(err){if(err.message!=='401')$('#loginMsg').textContent=err.message}});$('#logout').addEventListener('click',async()=>{try{await api('/api/cikis',{method:'POST',body:'{}'})}catch{}showLogin('Çıkış yapıldı.')});$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)tab(b.dataset.tab)});window.addEventListener('hashchange',()=>tab(location.hash.slice(1)));
$('#root').addEventListener('scroll',()=>hold(700),true);$('#root').addEventListener('wheel',()=>hold(900),{capture:true,passive:true});$('#root').addEventListener('pointerdown',()=>hold(900),true);$('#root').addEventListener('input',e=>{hold(1800);if(e.target.matches('input[type=range]')){const out=e.target.parentElement?.querySelector('[data-out]')||e.target.closest('label')?.querySelector('[data-price-out]');if(out)out.textContent=e.target.hasAttribute('data-cap')?int(e.target.value):money(e.target.value);updateCapTotal()}},true);
$('#root').addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='capacityForm'){const tahsisler={};e.target.querySelectorAll('[data-cap]').forEach(x=>tahsisler[x.dataset.cap]=Number(x.value));await post('/api/kapasite/tahsis',{tahsisler})}else if(e.target.id==='creditForm')await post('/api/kredi',{krediTuru:'isletme',tutar:Number($('#creditAmount').value)});else if(e.target.id==='passwordForm')await post('/api/parola',{eskiParola:$('#oldPass').value,yeniParola:$('#newPass').value})}catch(err){$('#toast').textContent=err.message}});
$('#root').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{const a=b.dataset.action;if(a==='invest')await post('/api/yatirim',{yatirimTuru:b.dataset.type});if(a==='service-toggle')await post('/api/hizmet/durum',{hizmetKimligi:b.dataset.service,hizmetSurumu:b.dataset.version,aktif:b.dataset.next==='true'});if(a==='sla')await post('/api/sozlesme/kabul',{teklifKimligi:b.dataset.offer});if(a==='adopt-proto')await post('/api/protokol/benimse',{protokolKimligi:b.dataset.market});if(a==='publish-proto')await post('/api/protokol/yayinla',{protokolKimligi:b.dataset.proto,surum:b.dataset.version,lisansModeli:'acik',benimsemeBedeli:0,tickLisansBedeli:0});if(a==='publish'){const c=b.closest('.product'),model=c.querySelector('[data-model]').value,price=Number(c.querySelector('[data-price]').value);await post('/api/uygulama/yayinla',{uygulamaKimligi:c.dataset.app,fiyatlandirmaModeli:model,abonelikUcreti:model==='kullanim'?0:price,kullanimBasinaUcret:model==='kullanim'?price:0,isletimSistemiKimligi:c.querySelector('[data-os]')?.value||'',baglantiProtokoluKimligi:c.querySelector('[data-proto]').value,aktifOlmasiIsteniyor:true})}if(a==='price'){const c=b.closest('.product'),price=Number(c.querySelector('[data-price]').value),u=(S.d.isletim?.urunler||[]).find(x=>x.urunKimligi===c.dataset.product);await post('/api/uygulama/guncelle',{urunKimligi:c.dataset.product,abonelikUcreti:u?.fiyatlandirmaModeli==='kullanim'?0:price,kullanimBasinaUcret:u?.fiyatlandirmaModeli==='kullanim'?price:0,aktif:c.querySelector('[data-active]').checked})}}catch(err){$('#toast').textContent=err.message}});
function updateCapTotal(){const f=$('#capacityForm');if(!f)return;const total=[...f.querySelectorAll('[data-cap]')].reduce((a,x)=>a+Number(x.value||0),0),max=Number(S.d?.v9?.kapasite?.toplamFizikselKapasite||0),el=$('#capTotal');if(el){el.textContent=`Ayrılan ${int(total)} / ${int(max)}`;el.className=`tag ${total>max?'bad':'good'}`}}
setInterval(()=>{if(S.pending&&!editing()&&Date.now()>=S.hold)render();if(S.auth)refresh(false)},1000);fetch('/api/saglik',{cache:'no-store'}).catch(()=>{});showLogin();
</script></body></html>
""";
}
